const PROFILE_KEY='gn_profile_v1';
function newProfileId(){try{return crypto.randomUUID()}catch{return `profile-${Date.now()}-${Math.random().toString(36).slice(2)}`}}
function normalizeProfile(raw={}){const avatar=avatarByKey[raw.avatar]?raw.avatar:'john',variant=Math.max(0,Number(raw.variant)||0),outfitVariant=Math.max(0,Number(raw.outfitVariant)||0),color=colors.includes(raw.color)?raw.color:'#2f6b4f',name=String(raw.name||localStorage.getItem('gn_name')||'').trim().slice(0,24);return {profileId:String(raw.profileId||newProfileId()).slice(0,80),name,avatar,variant,outfitVariant,color,tutorialProgress:raw.tutorialProgress&&typeof raw.tutorialProgress==='object'?raw.tutorialProgress:{}}}
function readSavedProfile(){try{return normalizeProfile(JSON.parse(localStorage.getItem(PROFILE_KEY)||'{}'))}catch{return normalizeProfile({})}}
let savedProfile=readSavedProfile();
function saveProfilePrefs(patch={}){savedProfile=normalizeProfile({...savedProfile,...patch,profileId:savedProfile.profileId||patch.profileId});localStorage.setItem(PROFILE_KEY,JSON.stringify(savedProfile));if(savedProfile.name)localStorage.setItem('gn_name',savedProfile.name);return savedProfile}
function profilePayload(extra={}){return {profileId:savedProfile.profileId,name:savedProfile.name||session?.name||'Player',avatar:savedProfile.avatar,variant:savedProfile.variant,outfitVariant:savedProfile.outfitVariant,color:savedProfile.color,...extra}}

