function tokenKey(kind,room=session.roomId){return room?`gn_${kind}_${room}`:`gn_${kind}`}
if(session.roomId){session.playerToken=localStorage.getItem(tokenKey('player'));session.hostToken=localStorage.getItem(tokenKey('host'))}

function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function pastGames(){try{return JSON.parse(localStorage.getItem('gn_game_history')||'[]')}catch{return[]}}
function saveGameSummary(s){if(!s||s.game?.phase!=='gameOver')return;const games=pastGames(),matchId=s.game.matchId||`${s.id}:${s.gameType}:${s.game.history.length}`;if(games.some(g=>g.matchId===matchId))return;const winners=s.game.winnerIds.map(id=>s.players.find(p=>p.id===id)?.name).filter(Boolean);games.unshift({matchId,roomId:s.id,at:Date.now(),game:s.gameName,rounds:s.game.history.length,winners,players:s.players.map(p=>({name:p.name,score:p.score,avatar:p.avatar}))});localStorage.setItem('gn_game_history',JSON.stringify(games.slice(0,50)))}
async function api(path,body={}){const r=await fetch(`/api/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Request failed');return data}
async function fetchState(room,token=''){const r=await fetch(`/api/state?room=${encodeURIComponent(room)}&token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!r.ok)throw new Error('Room not found');return r.json()}
function setError(e){session.error=e?.message||String(e);render();setTimeout(()=>{session.error=null;render()},3600)}
function inviteLink(){return `${location.origin}/?room=${session.roomId}`}
function directGameLink(key,prototype=false){return prototype?`${location.origin}/new-games.html?game=${encodeURIComponent(key)}`:`${location.origin}/?game=${encodeURIComponent(key)}`}
const suitSortOrder={clubs:0,diamonds:1,hearts:2,spades:3,joker:4,none:5};
const rankSortOrder={'A':14,'K':13,'Q':12,'J':11,'10':10,'9':9,'8':8,'7':7,'6':6,'5':5,'4':4,'3':3,'2':2};
function sortedCards(cards,type=session.state?.gameType){const arr=[...(cards||[])];return arr.sort((a,b)=>{if(a.kind||b.kind){const co={fire:0,forest:1,river:2,lantern:3,wild:4},ka=co[a.color]??8,kb=co[b.color]??8;if(ka!==kb)return ka-kb;const na=Number(a.rank),nb=Number(b.rank);if(Number.isFinite(na)&&Number.isFinite(nb))return na-nb;return String(a.rank||a.kind||'').localeCompare(String(b.rank||b.kind||''))}const sa=suitSortOrder[a.suit]??9,sb=suitSortOrder[b.suit]??9;if(sa!==sb)return sa-sb;const ra=rankSortOrder[a.rank]??(Number(a.rank)||0),rb=rankSortOrder[b.rank]??(Number(b.rank)||0);return ra-rb})}
function gameSwitcherOverlay(s){if(!session.gameSwitcherOpen||!s)return'';const count=s.players.length;return `<div class="game-switcher-backdrop"><section class="game-switcher"><div class="game-switcher-head"><div><strong>Keep the room · change the game</strong><small>Everyone stays together. Seats and Ready reset for the new game.</small></div><button class="choice-close" data-action="toggleGameSwitcher">×</button></div><div class="game-switcher-grid">${Object.entries(gameMeta).map(([key,m])=>{const tooMany=count>m.max,current=key===s.gameType;return `<button class="game-switch-choice ${current?'current':''}" data-switch-game="${key}" ${tooMany||current?'disabled':''}><span>${m.icon}</span><b>${esc(m.name)}</b><small>${current?'Current game':tooMany?`Max ${m.max} players`:`${m.min===m.max?m.min:`${m.min}-${m.max}`} players`}</small></button>`}).join('')}</div></section></div>`}
function topbar(){const canSwitch=!!(session.roomId&&session.hostToken&&session.state);return `<div class="topbar"><div class="brand"><div class="brand-mark">🂡</div><div>Black Family Game Night <span class="app-version">v${APP_VERSION}</span></div></div>${session.roomId?`<div class="topbar-actions">${canSwitch?`<button class="topbar-switch" data-action="toggleGameSwitcher" title="Move this room to another game">↻ Switch Game</button>`:''}<button class="topbar-home" data-action="home" title="Leave this room and return to the shelf">⌂ Game Shelf</button></div>`:''}</div>`}
function chatBannerHTML(){const m=session.chatBanner;if(!m)return'';return `<div class="chat-toast"><strong>${esc(m.name)}</strong><span>${esc(m.text)}</span></div>`}
function shell(inner){return `<div class="shell">${topbar()}${chatBannerHTML()}${session.error?`<div class="page"><div class="error">${esc(session.error)}</div></div>`:''}${inner}${gameSwitcherOverlay(session.state)}</div>`}

function johnLook(index=0){return johnLooks[((Number(index)||0)%johnLooks.length+johnLooks.length)%johnLooks.length]}
function avatarImagePath(p){const a=avatarByKey[p?.avatar]||avatars[0];if(a[0]==='john')return `/avatars/styles/${johnLook(p?.variant)[0]}.jpg`;const style=avatarStyles[(Number(p?.variant)||0)%avatarStyles.length][0];return `/avatars/styles/${a[0]}-${style}.jpg`}
function avatarHTML(p,cls='avatar'){const a=avatarByKey[p?.avatar]||avatars[0],color=p?.color||'#2f6b4f';const isJohn=a[0]==='john',style=isJohn?['john-birthday',johnLook(p?.variant)[1],johnLook(p?.variant)[2]]:avatarStyles[(Number(p?.variant)||0)%avatarStyles.length];return `<div class="${cls} avatar-frame style-${style[0]}" style="--pc:${color};--outfit:${color}" title="${esc(a[1])} · ${esc(style[1])}"><img src="${avatarImagePath(p)}" alt="${esc(a[1])}, ${esc(style[1])}"><span class="outfit-tint"></span></div>`}
