 if(t===GAME.EUCHRE)return `<div class="center-display"><h2>${e.trump?`${suitSymbol[e.trump]} ${suitName[e.trump]} TRUMP`:'CALLING TRUMP'}</h2><div class="feature-card">${extraCardHTML(e.upCard)}</div><div class="team-score-mini"><span>Team 1 <strong>${e.teamScores?.A??0}</strong></span><span>Team 2 <strong>${e.teamScores?.B??0}</strong></span></div><div class="trick-row">${(e.trick||[]).map(x=>extraCardHTML(x.card,true)).join('')}</div></div>`;
 if(t===GAME.CRIBBAGE)return cribBoard(s,e);
