async function joinRoom(){try{const name=document.querySelector('#joinName')?.value.trim()||savedProfile.name||'Player';session.name=name;saveProfilePrefs({name});const d=await api('join',{roomId:session.roomId,...profilePayload({name})});session.playerToken=d.playerToken;session.connectionIssue=false;localStorage.setItem(tokenKey('player'),d.playerToken);connect();render()}catch(e){setError(e)}}
function goHome(){session.events?.close();session.events=null;if(session.connectTimer)clearTimeout(session.connectTimer);if(session.pollTimer)clearInterval(session.pollTimer);if(session.botTimer)clearInterval(session.botTimer);session.connectTimer=null;session.pollTimer=null;session.botTimer=null;session.botBusy=false;session.roomId=null;session.playerToken=null;session.hostToken=null;session.state=null;session.preview=null;session.selectedCard=null;session.cardPlayPending=null;session.selectedBid=null;session.selectedExtraCard=null;session.connectionIssue=false;session.ceremonyDismissed=false;session.scheduleOpen=false;session.chatPrimed=false;session.lastChatId=null;session.chatBanner=null;session.marbleZoom=1;session.golfDiscardMode=false;session.selectedCribCards=[];session.selectedMarblePawn=null;if(session.chatBannerTimer)clearTimeout(session.chatBannerTimer);history.replaceState({},'','/');render()}

function bind(){
 document.querySelectorAll('[data-create-game]').forEach(el=>el.onclick=()=>createRoom(el.dataset.createGame));
 document.querySelectorAll('[data-create-share-game]').forEach(el=>el.onclick=()=>createRoom(el.dataset.createShareGame,true));
 document.querySelectorAll('[data-prototype-game]').forEach(el=>el.onclick=()=>{const key=el.dataset.prototypeGame;if(key==='prophunt')return createPropHuntRoom(false);if(key==='island')return createIslandRoom(false);location.href=`/new-games.html?game=${encodeURIComponent(key)}`});
 document.querySelectorAll('[data-share-game]').forEach(el=>el.onclick=async()=>{const key=el.dataset.shareGame,isPrototype=el.dataset.prototype==='1';if(isPrototype&&key==='prophunt')return createPropHuntRoom(true);if(isPrototype&&key==='island')return createIslandRoom(true);const url=directGameLink(key,isPrototype),title=(isPrototype?prototypeGames[key]:gameMeta[key])?.name||'Black Family Game Night';try{if(navigator.share)await navigator.share({title,text:`Play ${title} with me`,url});else{await navigator.clipboard.writeText(url);el.textContent='Link Copied!';setTimeout(render,900)}}catch{}});
 document.querySelectorAll('[data-home-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.homeAction;if(a==='games')document.querySelector('#newGamesShelf')?.scrollIntoView({behavior:'smooth'});else if(a==='lodge')document.querySelector('#gameLodgeShelf')?.scrollIntoView({behavior:'smooth'});else openHomePanel(a)});
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;try{
   if(a==='join')return joinRoom();if(a==='avatarBack'){session.avatarPickStage='character';render();return}if(a==='avatarDone'){session.avatarPickStage='outfit';return}if(a==='addBot'){const difficulty=document.querySelector('#botDifficulty')?.value||'medium',avatar=document.querySelector('#botCharacter')?.value||'auto';await api('addBot',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,difficulty,avatar:avatar==='auto'?null:avatar});return;}if(a==='toggleGameSwitcher'){session.gameSwitcherOpen=!session.gameSwitcherOpen;render();return}if(a==='retryConnect'){session.connectionIssue=false;session.state=null;connect();render();return}if(a==='copy'){await navigator.clipboard.writeText(inviteLink());el.textContent='Copied!';setTimeout(render,900);return}if(a==='shareInvite'){const title=session.state?.gameName||'Black Family Game Night',url=inviteLink();if(navigator.share){await navigator.share({title,text:`Join my ${title} game`,url})}else{await navigator.clipboard.writeText(url);el.textContent='Link Copied!';setTimeout(render,900)}return}if(a==='home')return goHome();if(a==='toggleSchedule'){session.scheduleOpen=!session.scheduleOpen;render();return}if(a==='dismissCeremony'){session.ceremonyDismissed=true;render();return}
   const b={roomId:session.roomId,playerToken:session.playerToken};
   if(a==='start')await api('start',{...b,hostToken:session.hostToken});
   if(a==='rematch'){await api('rematch',{...b,hostToken:session.hostToken});session.ceremonyDismissed=false;session.selectedCard=null;session.selectedExtraCard=null;session.selectedTrailCardId=null;session.selectedTrailPawn=null}
   if(a==='ready'){const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('ready',{...b,ready:!me.ready})}
   if(a==='saveProfile'){const me=session.state.players.find(p=>p.id===session.state.viewerId),name=document.querySelector('#profileName')?.value.trim()||me.name;session.name=name;saveProfilePrefs({name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:me.color});await api('profile',{...b,...profilePayload({name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:me.color})})}
      if(a==='saveSettings'){const payload={...b,hostToken:session.hostToken};document.querySelectorAll('[data-setting]').forEach(el=>{payload[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value});await api('settings',payload)}
   if(a==='confirmBid'){if(session.selectedBid==null)return;await api('bid',{...b,bid:session.selectedBid});session.selectedBid=null}
   if(a==='continue')await api('continue',b);
   if(a==='chat'){const input=document.querySelector('#chatInput'),text=input?.value.trim();if(text){await api('chat',{...b,text});input.value='';const fresh=await fetchState(session.roomId,session.playerToken);setRoomState(fresh);render()}}
 }catch(e){setError(e)}});
 const seat=document.querySelector('#seatSelect');if(seat)seat.onchange=async()=>{if(seat.value==='')return;try{await api('seat',{roomId:session.roomId,playerToken:session.playerToken,seat:Number(seat.value)})}catch(e){setError(e)}};
 document.querySelectorAll('[data-avatar]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId),target=el.dataset.avatar;const variant=target==='john'?(me.avatar==='john'?Number(me.variant||1):1):(me.avatar==='john'?0:Number(me.variant||0)%avatarStyles.length);me.avatar=target;me.variant=variant;session.avatarPickStage='outfit';render();await api('profile',{roomId:session.roomId,playerToken:session.playerToken,profileId:savedProfile.profileId,name:me.name,avatar:target,variant,outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-color]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,profileId:savedProfile.profileId,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:el.dataset.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-style]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,profileId:savedProfile.profileId,name:me.name,avatar:me.avatar,variant:Number(el.dataset.style),outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-outfit]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,profileId:savedProfile.profileId,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:Number(el.dataset.outfit),color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-update-bot]').forEach(el=>el.onclick=async()=>{try{const id=el.dataset.updateBot,avatar=document.querySelector(`[data-bot-character="${id}"]`)?.value,difficulty=document.querySelector(`[data-bot-difficulty="${id}"]`)?.value;await api('updateBot',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,targetId:id,avatar,difficulty});}catch(e){setError(e)}});
 document.querySelectorAll('[data-remove-player]').forEach(el=>el.onclick=async()=>{try{await api('removePlayer',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,targetId:el.dataset.removePlayer})}catch(e){setError(e)}});
 document.querySelectorAll('[data-bid]').forEach(el=>el.onclick=()=>{session.selectedBid=session.state?.gameType===GAME.SMEAR?el.dataset.bid:Number(el.dataset.bid);render()});
 document.querySelectorAll('[data-card]').forEach(el=>el.onclick=()=>playStandardCardNow(el.dataset.card,el));
 document.querySelectorAll('[data-extra-card]').forEach(el=>el.onclick=()=>{session.selectedExtraCard=el.dataset.extraCard;session.selectedMarblePawn=null;render()});
 document.querySelectorAll('[data-extra-card-clear]').forEach(el=>el.onclick=()=>{session.selectedExtraCard=null;render()});
 document.querySelectorAll('[data-extra-action]').forEach(el=>el.onclick=async()=>{if(session.extraActionPending)return;try{const e=session.state?.game?.extra,a=e?.actions?.[Number(el.dataset.extraAction)];if(!a)return;session.extraActionPending=true;el.disabled=true;await api('gameAction',{roomId:session.roomId,playerToken:session.playerToken,action:a.action,args:a.args||{}});session.selectedExtraCard=null;if(e.type===GAME.TRAIL){session.selectedTrailCardId=null;session.selectedTrailPawn=null}}catch(err){setError(err)}finally{session.extraActionPending=false}});
 document.querySelectorAll('[data-switch-game]').forEach(el=>el.onclick=async()=>{try{await api('switchGame',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,gameType:el.dataset.switchGame});session.gameSwitcherOpen=false}catch(err){setError(err)}});
 document.querySelectorAll('[data-trail-zoom]').forEach(el=>el.onclick=()=>{const a=el.dataset.trailZoom;if(a==='reset'){session.trailZoom=1;session.trailPanX=0;session.trailPanY=0;session.trailManualView=false}else if(a==='in')session.trailZoom=Math.min(2.5,(Number(session.trailZoom)||1)+.2);else session.trailZoom=Math.max(.78,(Number(session.trailZoom)||1)-.2);render()});
 document.querySelectorAll('[data-trail-card-select]').forEach(el=>el.onclick=()=>{if(Date.now()<session.trailSuppressClickUntil)return;session.selectedTrailCardId=el.dataset.trailCardSelect;session.selectedTrailPawn=null;render()});
 document.querySelectorAll('[data-trail-pawn]:not([data-extra-action])').forEach(el=>el.onclick=()=>{if(Date.now()<session.trailSuppressClickUntil||!session.selectedTrailCardId)return;session.selectedTrailPawn=el.dataset.trailPawn;render()});
 document.querySelectorAll('[data-trail-clear-pawn]').forEach(el=>el.onclick=()=>{session.selectedTrailPawn=null;render()});
 document.querySelectorAll('[data-golf-mode]').forEach(el=>el.onclick=()=>{session.golfDiscardMode=!session.golfDiscardMode;render()});
 document.querySelectorAll('[data-marble-zoom]').forEach(el=>el.onclick=()=>{const a=el.dataset.marbleZoom;if(a==='reset')session.marbleZoom=1;else if(a==='in')session.marbleZoom=Math.min(2.4,(Number(session.marbleZoom)||1)+.25);else session.marbleZoom=Math.max(1,(Number(session.marbleZoom)||1)-.25);render()});
 document.querySelectorAll('[data-marble-pawn]').forEach(el=>el.onclick=()=>{session.selectedMarblePawn=el.dataset.marblePawn;const e=session.state?.game?.extra,hits=(e?.actions||[]).map((a,i)=>[a,i]).filter(([a])=>actionCardIds(a).includes(session.selectedExtraCard)&&[a.args?.pawnId,a.args?.a,a.args?.b].includes(session.selectedMarblePawn));if(hits.length===1){api('gameAction',{roomId:session.roomId,playerToken:session.playerToken,action:hits[0][0].action,args:hits[0][0].args||{}}).then(()=>{session.selectedExtraCard=null;session.selectedMarblePawn=null}).catch(setError)}else render()});
 document.querySelectorAll('[data-crib-card]').forEach(el=>el.onclick=()=>{const id=el.dataset.cribCard,need=session.state?.game?.extra?.discardNeed||2,sel=session.selectedCribCards||[];session.selectedCribCards=sel.includes(id)?sel.filter(x=>x!==id):sel.length<need?[...sel,id]:[...sel.slice(1),id];render()});
 document.querySelectorAll('[data-crib-send]').forEach(el=>el.onclick=async()=>{try{const e=session.state?.game?.extra,sel=[...(session.selectedCribCards||[])].sort(),hit=(e?.actions||[]).find(a=>a.action==='cribDiscard'&&[...(a.args?.cardIds||[])].sort().join('|')===sel.join('|'));if(!hit)throw new Error('Choose the required crib cards');await api('gameAction',{roomId:session.roomId,playerToken:session.playerToken,action:hit.action,args:hit.args||{}});session.selectedCribCards=[]}catch(err){setError(err)}});
 document.querySelectorAll('[data-react]').forEach(el=>el.onclick=()=>api('react',{roomId:session.roomId,playerToken:session.playerToken,emoji:el.dataset.react}).catch(setError));
 const chat=document.querySelector('#chatInput');if(chat)chat.onkeydown=e=>{if(e.key==='Enter')document.querySelector('[data-action="chat"]')?.click()};bindTrailBoardGestures();const requested=new URL(location.href).searchParams.get('game');if(requested){const card=document.querySelector(`[data-game-card="${CSS.escape(requested)}"]`);if(card){card.classList.add('requested-game');setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'center'}),120)}}
}

if(session.roomId&&!session.playerToken)loadPreview();
render();if(session.roomId&&session.playerToken)connect();
